mapper.select:
SELECT COUNT(*)
FROM violate_mgmt
WHERE deleted = 0

    AND violate_type = #{violateType}


    AND violate_time >= #{startTime}


    AND violate_time <= #{endTime}


    AND status = #{status}

SELECT COUNT(student_id) count FROM violate_mgmt WHERE deleted = 0
AND violate_time >= #{startTime}
AND violate_time <= #{endTime}
GROUP BY student_id HAVING count >=3

SELECT violate_type, COUNT(*) count FROM violate_mgmt WHERE deleted = 0
AND violate_time >= #{startTime}
AND violate_time <= #{endTime}
GROUP BY violate_type
